import com.android.build.api.artifact.SingleArtifact
import groovy.json.JsonSlurper
import java.io.ByteArrayOutputStream
import java.util.Properties
import javax.inject.Inject

// The Rainy watch face: a Watch Face Format face, resources only (no code), published on Google Play as its own app
// (app.wakirox.rainy.watchface; the watch app links to its listing). Its sources in src/main are generated by
// tools/generate.py; its Play files (release notes) are in src/release/play. See README.md.
plugins {
    alias(libs.plugins.android.application)
    alias(libs.plugins.play.publisher)
}

// Release signing from keystore.properties at the repo root (gitignored); without it the release build is unsigned.
val releaseKeystore: Properties? = rootProject.file("keystore.properties").takeIf { it.exists() }?.let { file ->
    Properties().apply { file.inputStream().use { load(it) } }
}

android {
    namespace = "app.wakirox.rainy.watchface"
    compileSdk = 37

    defaultConfig {
        // Its own Play app, apart from the phone and watch apps (app.wakirox.rainy): Play doesn't take a watch face in
        // the same bundle as a Wear OS app's code.
        applicationId = "app.wakirox.rainy.watchface"
        // Wear OS 7 (API 37): the face is Watch Face Format 5 (tools/generate.py), which Wear OS 6 doesn't
        // install.
        minSdk = 37
        targetSdk = 37
        // Its own version (gradle.properties), bumped when the face changes; Play rejects a code it has seen.
        versionCode = providers.gradleProperty("face.versionCode").get().toInt()
        versionName = providers.gradleProperty("face.versionName").get()
    }

    // No code at all: the manifest says hasCode="false"; the APK holds the manifest, resources.arsc, res/ and META-INF/
    // only (no Kotlin runtime, no BuildConfig, no dex).
    enableKotlin = false
    buildFeatures {
        buildConfig = false
        resValues = false
    }

    // Signed with the key in keystore.properties (the upload key); Play re-signs with its own.
    signingConfigs {
        if (releaseKeystore != null) {
            create("release") {
                storeFile = file(releaseKeystore.getProperty("storeFile"))
                storePassword = releaseKeystore.getProperty("storePassword")
                keyAlias = releaseKeystore.getProperty("keyAlias")
                keyPassword = releaseKeystore.getProperty("keyPassword")
            }
        }
    }

    buildTypes {
        // R8 with no code to keep drops the R class, so the APK has no classes.dex. No resource shrinking: nothing
        // references the face's resources (raw/watchface.xml...), the system reads them by name.
        debug {
            isMinifyEnabled = true
        }
        release {
            isMinifyEnabled = true
            isShrinkResources = false
            // Unsigned without keystore.properties, so a debug-signed build can't be uploaded by mistake.
            if (releaseKeystore != null) signingConfig = signingConfigs.getByName("release")
        }
    }

    // Until tools/generate.py has written src/main, a build can point at other face sources (a directory
    // with AndroidManifest.xml and res/): -Prainy.watchFaceSources=/path/to/face.
    providers.gradleProperty("rainy.watchFaceSources").orNull?.let { dir ->
        sourceSets.getByName("main") {
            manifest.srcFile("$dir/AndroidManifest.xml")
            res.setSrcDirs(listOf("$dir/res"))
        }
    }

    // Only the release build goes to Play.
    playConfigs {
        register("debug") {
            enabled.set(false)
        }
    }
}

// Google Play (Gradle Play Publisher): `publishReleaseBundle` uploads the
// bundle to the internal track. Credentials: a service account's JSON key, from the ANDROID_PUBLISHER_CREDENTIALS
// environment variable or play-credentials.json at the repo root (gitignored). The Play app must exist
// first (README.md): until then publishing fails with Play Publisher's "No application found for the package
// name 'app.wakirox.rainy.watchface'. The first version of your app must be uploaded via the Play Console."
play {
    rootProject.file("play-credentials.json").takeIf { it.exists() }?.let { serviceAccountCredentials.set(it) }
    defaultToAppBundles.set(true)
    track.set("internal")
}

// Google's Watch Face Push validator, though the face isn't pushed: the most complete validator Google ships on Maven.
// It checks the Watch Face Format schema (v5), the memory footprint (Play's quality budget: 10 MB ambient, 100 MB
// interactive), the APK contents (manifest, resources.arsc, res/ and META-INF/ only), the manifest's format version
// property, the minimum SDK and the signature. Its one Push-only check, the package name (<pushing
// app>.watchfacepush.<face>), fails by design and is ignored. `validate<Variant>WatchFace`; a signed release bundle
// (so every upload to Play) validates its APK first. The debug one is always signed.
val watchFaceValidator = configurations.create("watchFaceValidator") {
    isCanBeConsumed = false
    isTransitive = false
}
dependencies { watchFaceValidator(libs.watchface.validator.push.cli) }

androidComponents.onVariants { variant ->
    val name = variant.name.replaceFirstChar(Char::titlecase)
    val validate = tasks.register<ValidateWatchFaceTask>("validate${name}WatchFace") {
        group = "verification"
        description = "Validates the $name watch face APK with Google's Watch Face Push validator."
        apkDirectory.set(variant.artifacts.get(SingleArtifact.APK))
        validator.from(watchFaceValidator)
        report.set(layout.buildDirectory.file("reports/watchface/${variant.name}-validation.txt"))
    }
    // An unsigned release (no keystore.properties, as in CI) would fail the signature check, and can't go to Play.
    if (variant.buildType != "release" || releaseKeystore != null) {
        tasks.matching { it.name == "bundle$name" }.configureEach { dependsOn(validate) }
    }
}

/** Runs the Watch Face Push validator on the face APK and fails on any failing check except the package-name one. */
@CacheableTask
abstract class ValidateWatchFaceTask : DefaultTask() {
    /** The face's APK directory (the APK and output-metadata.json). */
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.NAME_ONLY)
    abstract val apkDirectory: DirectoryProperty

    @get:Classpath
    abstract val validator: ConfigurableFileCollection

    @get:OutputFile
    abstract val report: RegularFileProperty

    @get:Inject
    abstract val exec: ExecOperations

    @TaskAction
    fun validate() {
        val directory = apkDirectory.get().asFile
        val metadata = JsonSlurper().parse(directory.resolve("output-metadata.json")) as Map<*, *>
        val element = (metadata["elements"] as List<*>).single() as Map<*, *>
        val apk = directory.resolve(element["outputFile"] as String)

        val output = ByteArrayOutputStream()
        exec.javaexec {
            classpath(validator)
            mainClass.set("com.google.android.wearable.watchface.validator.cli.DwfValidation")
            // Any client package: the face isn't pushed, the token (if any) is dropped.
            args("--apk_path=${apk.absolutePath}", "--package_name=app.wakirox.rainy")
            workingDir = temporaryDir
            standardOutput = output
            errorOutput = output
            isIgnoreExitValue = true
        }
        val text = output.toString().lines().filterNot { it.contains("generated token") }.joinToString("\n")
        report.get().asFile.writeText(text)

        val check = Regex("(Failed|Successful) check: Check\\w+\\{name=([^,}]+)")
        fun checks(kind: String) = check.findAll(text).filter { it.groupValues[1] == kind }.map { it.groupValues[2] }.toList()
        val failed = checks("Failed") - "Package name"
        val passed = checks("Successful")
        // A validator whose output no longer reads as expected must not pass silently.
        val required =
            listOf("Watch Face Format validator run", "Memory footprint validation", "File contents validation")
        if (failed.isNotEmpty() || !passed.containsAll(required)) {
            throw GradleException("The watch face ${apk.name} failed validation:\n$text")
        }
    }
}
